UPDATE emp03_trans
   SET emp03_trans_date   = #{req.startDate}::date
     , emp03_org_code_id  = #{req.orgCodeId}
     , emp03_pos_cd       = #{req.posCd}
     , emp03_title_cd     = #{req.titleCd}
     , emp03_trans_reason = #{req.transReason}
     , emp03_org_head_yn  = #{req.orgHeadYn}
 WHERE emp03_person_id = #{req.transPersonId}
   AND emp03_person_id IN (SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId})

UPDATE emp04_add_title
   SET emp04_org_code_id  = #{req.orgCodeId}
     , emp04_start_date   = #{req.startDate}::date
     , emp04_close_date   = #{req.closeDate}::date
     , emp04_title_cd     = #{req.titleCd}
     , emp04_trans_reason = #{req.transReason}
 WHERE emp04_add_title_id = #{req.addTitleId}
   AND emp04_person_id IN (SELECT emp01_person_id FROM emp01_person WHERE emp01_company_id = #{companyId})

